CREATE OR REPLACE FUNCTION public.fn_job_ack(p_job_id uuid, p_lease_owner text, p_summary text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_enabled    boolean;
    v_state      text;
    v_owner      text;
    v_now        timestamptz := now();
BEGIN
    SELECT (value = 'true') INTO v_enabled
    FROM public.dot_config WHERE key = 'queue.job_substrate.enabled';
    v_enabled := COALESCE(v_enabled, false);
    IF NOT v_enabled THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'queue.job_substrate.enabled=false');
    END IF;

    SELECT state, lease_owner INTO v_state, v_owner
    FROM public.job_queue WHERE job_id = p_job_id FOR UPDATE;
    IF v_state IS NULL THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'job_not_found', 'job_id', p_job_id);
    END IF;
    IF v_state NOT IN ('leased','in_progress') THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'invalid_state_transition', 'current_state', v_state, 'job_id', p_job_id);
    END IF;
    IF v_owner IS DISTINCT FROM p_lease_owner THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'lease_owner_mismatch', 'expected', v_owner, 'got', p_lease_owner, 'job_id', p_job_id);
    END IF;

    UPDATE public.job_queue
    SET state = 'succeeded', finished_at = v_now,
        lease_owner = NULL, lease_until = NULL, last_error = NULL,
        updated_at = v_now
    WHERE job_id = p_job_id;

    RETURN jsonb_build_object('refused', false, 'job_id', p_job_id, 'state', 'succeeded', 'finished_at', v_now, 'summary', p_summary);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_job_claim(p_lease_owner text, p_job_kinds text[] DEFAULT NULL::text[], p_limit integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_enabled       boolean;
    v_lease_dur     integer;
    v_now           timestamptz := now();
    v_until         timestamptz;
    v_claimed       jsonb;
BEGIN
    SELECT (value = 'true') INTO v_enabled
    FROM public.dot_config WHERE key = 'queue.job_substrate.enabled';
    v_enabled := COALESCE(v_enabled, false);
    IF NOT v_enabled THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'queue.job_substrate.enabled=false', 'claimed', '[]'::jsonb);
    END IF;

    IF p_lease_owner IS NULL OR btrim(p_lease_owner) = '' THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'lease_owner_required', 'claimed', '[]'::jsonb);
    END IF;

    SELECT value::integer INTO v_lease_dur
    FROM public.dot_config WHERE key = 'queue.lease.duration_sec';
    v_lease_dur := COALESCE(v_lease_dur, 300);
    v_until := v_now + (v_lease_dur::text || ' seconds')::interval;

    WITH cte AS (
        SELECT job_id
        FROM public.job_queue
        WHERE state IN ('queued','retry_waiting')
          AND scheduled_at <= v_now
          AND (p_job_kinds IS NULL OR job_kind = ANY (p_job_kinds))
        ORDER BY priority ASC, scheduled_at ASC, created_at ASC
        FOR UPDATE SKIP LOCKED
        LIMIT GREATEST(COALESCE(p_limit, 1), 1)
    ),
    upd AS (
        UPDATE public.job_queue q
        SET state = 'leased',
            lease_owner = p_lease_owner,
            lease_until = v_until,
            picked_at = v_now,
            updated_at = v_now
        FROM cte
        WHERE q.job_id = cte.job_id
        RETURNING q.job_id, q.job_kind, q.payload_ref, q.payload_json,
                  q.source_ref, q.target_ref, q.priority, q.attempts,
                  q.max_attempts, q.idempotency_key, q.actor, q.run_id,
                  q.lease_owner, q.lease_until
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(upd.*)), '[]'::jsonb) INTO v_claimed FROM upd;

    RETURN jsonb_build_object(
        'refused', false,
        'lease_owner', p_lease_owner,
        'lease_until', v_until,
        'count', jsonb_array_length(v_claimed),
        'claimed', v_claimed
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_job_enqueue(p_job_kind text, p_actor text, p_payload_ref text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_source_ref text DEFAULT NULL::text, p_target_ref text DEFAULT NULL::text, p_priority integer DEFAULT 100, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_idempotency_key text DEFAULT NULL::text, p_max_attempts integer DEFAULT NULL::integer, p_run_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_enabled       boolean;
    v_idem          text;
    v_max           integer;
    v_cfg_max       integer;
    v_job_id        uuid;
    v_existing_id   uuid;
    v_existing_state text;
    v_now           timestamptz := now();
BEGIN
    SELECT (value = 'true') INTO v_enabled
    FROM public.dot_config WHERE key = 'queue.job_substrate.enabled';
    v_enabled := COALESCE(v_enabled, false);
    IF NOT v_enabled THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'queue.job_substrate.enabled=false', 'job_id', NULL);
    END IF;

    v_idem := COALESCE(NULLIF(btrim(p_idempotency_key), ''), gen_random_uuid()::text);
    SELECT value::integer INTO v_cfg_max
    FROM public.dot_config WHERE key = 'queue.retry.max_attempts_default';
    v_max := COALESCE(p_max_attempts, v_cfg_max, 5);

    SELECT job_id, state INTO v_existing_id, v_existing_state
    FROM public.job_queue
    WHERE idempotency_key = v_idem
      AND state IN ('queued','leased','in_progress','retry_waiting')
    LIMIT 1;
    IF v_existing_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'refused', false, 'duplicate', true,
            'job_id', v_existing_id, 'state', v_existing_state,
            'idempotency_key', v_idem
        );
    END IF;

    INSERT INTO public.job_queue (
        job_kind, state, source_ref, target_ref, payload_ref, payload_json,
        priority, scheduled_at, attempts, max_attempts, idempotency_key,
        actor, run_id, created_at, updated_at
    ) VALUES (
        p_job_kind, 'queued', p_source_ref, p_target_ref, p_payload_ref,
        COALESCE(p_payload_json, '{}'::jsonb),
        COALESCE(p_priority, 100),
        COALESCE(p_scheduled_at, v_now),
        0, v_max, v_idem,
        p_actor, p_run_id, v_now, v_now
    ) RETURNING job_id INTO v_job_id;

    RETURN jsonb_build_object(
        'refused', false, 'duplicate', false,
        'job_id', v_job_id, 'state', 'queued',
        'idempotency_key', v_idem,
        'max_attempts', v_max,
        'scheduled_at', COALESCE(p_scheduled_at, v_now)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_job_fail_or_retry(p_job_id uuid, p_lease_owner text, p_error_message text, p_permanent boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_enabled    boolean;
    v_row        public.job_queue%ROWTYPE;
    v_now        timestamptz := now();
    v_new_attempts integer;
    v_base       integer;
    v_backoff    integer;
    v_next       timestamptz;
    v_dl         jsonb;
BEGIN
    SELECT (value = 'true') INTO v_enabled
    FROM public.dot_config WHERE key = 'queue.job_substrate.enabled';
    v_enabled := COALESCE(v_enabled, false);
    IF NOT v_enabled THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'queue.job_substrate.enabled=false');
    END IF;

    SELECT * INTO v_row FROM public.job_queue WHERE job_id = p_job_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'job_not_found', 'job_id', p_job_id);
    END IF;
    IF v_row.state NOT IN ('leased','in_progress') THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'invalid_state_transition', 'current_state', v_row.state, 'job_id', p_job_id);
    END IF;
    IF v_row.lease_owner IS DISTINCT FROM p_lease_owner THEN
        RETURN jsonb_build_object('refused', true, 'reason', 'lease_owner_mismatch', 'expected', v_row.lease_owner, 'got', p_lease_owner, 'job_id', p_job_id);
    END IF;

    v_new_attempts := v_row.attempts + 1;

    IF p_permanent OR v_new_attempts >= v_row.max_attempts THEN
        UPDATE public.job_queue
        SET attempts = v_new_attempts, last_error = p_error_message, updated_at = v_now
        WHERE job_id = p_job_id;
        v_dl := public.fn_job_move_to_dead_letter(p_job_id, p_lease_owner, p_error_message);
        RETURN jsonb_build_object('refused', false, 'job_id', p_job_id, 'state', 'dead_letter', 'attempts', v_new_attempts, 'dead_letter', v_dl);
    END IF;

    SELECT value::integer INTO v_base
    FROM public.dot_config WHERE key = 'queue.retry.backoff_base_sec';
    v_base := COALESCE(v_base, 10);
    v_backoff := v_base * (1 << LEAST(v_new_attempts - 1, 10));
    v_next := v_now + (v_backoff::text || ' seconds')::interval;

    UPDATE public.job_queue
    SET state = 'retry_waiting',
        attempts = v_new_attempts,
        last_error = p_error_message,
        scheduled_at = v_next,
        lease_owner = NULL, lease_until = NULL,
        updated_at = v_now
    WHERE job_id = p_job_id;

    RETURN jsonb_build_object('refused', false, 'job_id', p_job_id, 'state', 'retry_waiting', 'attempts', v_new_attempts, 'max_attempts', v_row.max_attempts, 'backoff_sec', v_backoff, 'scheduled_at', v_next);
END;
$function$
